// src/components/Footer.jsx
import React from 'react';

const Footer = () => {
  return (
    <footer className="bg-studentDark text-white p-6 mt-8">
      <div className="container mx-auto text-center">
        <p className="text-lg font-bold mb-2">فرصتي</p>
        <p className="text-gray-400 mb-4">
          منصة لربط الطلاب بأفضل فرص التدريب والعمل.
        </p>
        <div className="flex justify-center space-x-4 mb-4">
          <a href="#" className="text-gray-300 hover:text-white transition duration-200">
            الخصوصية
          </a>
          <a href="#" className="text-gray-300 hover:text-white transition duration-200">
            الشروط
          </a>
          <a href="#" className="text-gray-300 hover:text-white transition duration-200">
            اتصل بنا
          </a>
        </div>
        <p className="text-gray-500 text-sm">
          &copy; {new Date().getFullYear()} My opportunity.Allri
        </p>
      </div>
    </footer>
  );
};

export default Footer;
